-- ============================================================
-- Permission Table Master Seed — 50-gap, 4-digit IDs
-- PermissionId = SortOrder (always in sync)
-- Primary entity first per module, rest A-Z
-- Actions: View, Create/Edit, Delete first, then specific actions
-- DisplayNames follow cleanup standard
-- ============================================================

DELETE FROM RolePermission;
DELETE FROM Permission;
DBCC CHECKIDENT ('Permission', RESEED, 0);

SET IDENTITY_INSERT Permission ON;

