-- VERIFY
SELECT PermissionType, COUNT(*) AS Cnt FROM Permission GROUP BY PermissionType ORDER BY PermissionType;
SELECT COUNT(*) AS TotalPermissions FROM Permission;
SELECT CASE WHEN COUNT(*) = 0 THEN 'OK: PermissionId = SortOrder for all rows' ELSE 'ERROR: Mismatch found!' END AS IdSortCheck
FROM Permission WHERE PermissionId != SortOrder;
